<?php
namespace Tests\Feature;use App\Models\{Offer,Product,Store};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class SizeFilteringTest extends TestCase {use RefreshDatabase;public function test_lowest_price_only_uses_available_selected_size():void{$p=Product::create(['brand'=>'ASICS','name'=>'ASICS TEST','model'=>'TEST','slug'=>'test']);foreach([[250,['42','43']],[280,['44','45']]] as $i=>$row){$s=Store::create(['name'=>'S'.$i,'slug'=>'s'.$i,'website_url'=>'https://example.com']);$o=Offer::create(['product_id'=>$p->id,'store_id'=>$s->id,'external_id'=>(string)$i,'name_original'=>'Test','price'=>$row[0],'currency'=>'BAM','availability'=>'in_stock','product_url'=>'https://example.com/'.$i,'last_checked_at'=>now()]);foreach($row[1] as $size)$o->variants()->create(['size'=>$size,'availability'=>'in_stock']);}$offers=$p->offers()->whereHas('variants',fn($q)=>$q->where('size','44')->where('availability','in_stock'));$this->assertEquals(280.00,$offers->min('price'));}}
